static const char *tag_out = "/app/lagpipe/synctab_out/procance.tag";
static const char *guard_out = "/app/lagpipe/synctab_out/offline_guard.ok";

static void clear_outputs(void) {
    remove(types_out);
    remove(tag_out);
    remove(guard_out);
}

static int write_one_line(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        return -1;
    }
    if (fprintf(fp, "%s\n", value) < 0 || fclose(fp) != 0) {
        remove(path);
        return -1;
    }
    return 0;
}

static int run_gen(void) {
    source_pick pick;

    clear_outputs();
    if (choose_layout(&pick) != 0) {
        fprintf(stderr, "imprint: layout pick failed\n");
        return 1;
    }
    if (pick.from_bundle || permit_tag(pick.tag_value) != 0) {
        fprintf(stderr, "imprint: bundle origin forbidden\n");
        clear_outputs();
        return 1;
    }
    if (write_types_tab(pick.layout_path, types_out, pick.tag_value) != 0) {
        fprintf(stderr, "imprint: types write failed\n");
        clear_outputs();
        return 1;
    }
    if (write_one_line(tag_out, pick.tag_value) != 0) {
        perror("imprint: procance.tag");
        clear_outputs();
        return 1;
    }
    if (rebuild_binary() != 0) {
        fprintf(stderr, "imprint: rebuild failed\n");
        clear_outputs();
